    59	/// Deliberately stricter than native StarRocks, which samples `schema_sample_file_count`
    60	/// files and promotes conflicting types: the scan reads every file with the inferred
    61	/// schema, so whole-set agreement is the correct fail-closed contract here.
    62	pub(crate) async fn parquet_files_schema(paths: &[String]) -> Result<Vec<PSlotDescriptor>, String> {
    63	    let (first, rest) = paths
    64	        .split_first()
    65	        .ok_or_else(|| "no file paths to infer a schema from".to_string())?;
    66	    let slots = parquet_file_schema(first).await?;
    67	    for path in rest {
    68	        let other = parquet_file_schema(path).await?;
